<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const gridSize = 32;
        const player = { x: 0, y: 0 };
        const tiles = {};
        const inventory = { seeds: 5, crops: 0 };
        let day = 0;

        function drawPlayer() {
            ctx.fillStyle = 'green';
            ctx.fillRect(player.x * gridSize, player.y * gridSize, gridSize, gridSize);
        }

        function drawTiles() {
            for (const tile in tiles) {
                const { crop, stage } = tiles[tile];
                ctx.fillStyle = crop === 'grain' ? 'yellow' : 'red';
                ctx.fillRect(tile[0] * gridSize, tile[1] * gridSize, gridSize, gridSize);
            }
        }

        function drawInventory() {
            ctx.fillStyle = 'blue';
            ctx.font = '16px Arial';
            ctx.fillText(`Seeds: ${inventory.seeds}`, 10, 20);
            ctx.fillText(`Crops: ${inventory.crops}`, 10, 40);
        }

        function drawDay() {
            ctx.fillStyle = 'purple';
            ctx.font = '16px Arial';
            ctx.fillText(`Day: ${day}`, 10, 60);
        }

        function update() {
            const keys = {
                37: () => player.x -= 1,
                38: () => player.y -= 1,
                39: () => player.x += 1,
                40: () => player.y += 1,
                80: () => plantSeed(),
                84: () => advanceTime(),
                72: () => harvestCrop(),
                83: () => saveGame(),
                68: () => restoreGame()
            };

            keys[window.event.keyCode] && keys[window.event.keyCode]();

            drawPlayer();
            drawTiles();
            drawInventory();
            drawDay();
            requestAnimationFrame(update);
        }

        function plantSeed() {
            const { x, y } = player;
            const tile = `${x},${y}`;
            if (!tiles[tile]) {
                tiles[tile] = { crop: 'grain', stage: 0 };
                inventory.seeds--;
            }
        }

        function advanceTime() {
            const tile = `${player.x},${player.y}`;
            if (tiles[tile]) {
                tiles[tile].stage++;
                if (tiles[tile].stage === 3) {
                    inventory.crops++;
                    delete tiles[tile];
                }
            }
        }

        function harvestCrop() {
            const { x, y } = player;
            const tile = `${x},${y}`;
            if (tiles[tile]) {
                inventory.crops--;
                delete tiles[tile];
            }
        }

        function saveGame() {
            localStorage.setItem('game', JSON.stringify({ player, tiles, inventory, day }));
        }

        function restoreGame() {
            const savedGame = localStorage.getItem('game');
            if (savedGame) {
                const { player, tiles, inventory, day } = JSON.parse(savedGame);
                player = player;
                tiles = tiles;
                inventory = inventory;
                day = day;
            }
        }

        update();
    </script>
</body>
</html>
